The domain should be configurable.

---

### Suggested Refactor

```javascript
const express = require('express');
const app = express();

const PORT = process.env.PORT || 3000;
const DOMAIN = process.env.DOMAIN || 'example.com';
const USERS = process.env.USERS ? JSON.parse(process.env.USERS) : [
  { id: 1, name: 'Alice', email: `alice@${DOMAIN}` },
  { id: 2, name: 'Bob', email: `bob@${DOMAIN}` },
];

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json(USERS);
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

---

### Other Observations

- `console.log` with server info could leak port in production logs - consider removing or making conditional
- No other files exist in this project to check

